package com.buildplanner;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Reads an immutable set published by the EDT; never touches Swing or planner state. */
public final class BuildBankOverlay extends WidgetItemOverlay
{
    private final BuildPlannerPlugin plugin;
    private final BuildPlannerConfig config;
    @Inject BuildBankOverlay(BuildPlannerPlugin plugin, BuildPlannerConfig config)
    {
        this.plugin = plugin; this.config = config;
        drawAfterLayer(InterfaceID.Bankmain.ITEMS);
    }
    @Override public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem item)
    {
        if (!config.highlightBank() || !plugin.bankItems().contains(itemId) || item.getQuantity() <= 0) return;
        Rectangle bounds = item.getCanvasBounds();
        Graphics2D g = (Graphics2D) graphics.create();
        try {
            g.setColor(new Color(208, 178, 112, 45));
            g.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
            g.setColor(new Color(208, 178, 112));
            g.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
        } finally { g.dispose(); }
    }
}

package com.buildplanner;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("buildplanner")
public interface BuildPlannerConfig extends Config
{
    @ConfigItem(keyName = "highlightBank", name = "Automatic bank highlighting",
        description = "Highlight bank materials for unfinished builds in the selected project.", position = 0)
    default boolean highlightBank() { return false; }
}

package com.buildplanner;

import com.google.gson.Gson;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

@PluginDescriptor(name = "Build Planner", description = "Search Sailing and house recipes and plan materials", tags = {"construction", "sailing", "recipes", "materials", "planner"})
public final class BuildPlannerPlugin extends Plugin
{
    static final String GROUP = "buildplanner";
    static final String STATE = "projectsV1";
    @Inject private ClientToolbar toolbar;
    @Inject private ConfigManager config;
    @Inject private Gson gson;
    @Inject private net.runelite.client.game.ItemManager itemManager;
    @Inject private net.runelite.api.Client client;
    @Inject private net.runelite.client.config.RuneLiteConfig runeLiteConfig;
    @Inject private net.runelite.client.ui.overlay.OverlayManager overlayManager;
    @Inject private BuildBankOverlay bankOverlay;
    private volatile java.util.Set<Integer> bankItems = java.util.Set.of();
    private int construction = -1, sailing = -1;
    private volatile LiveSupplies live;

    @com.google.inject.Provides
    BuildPlannerConfig provideConfig(ConfigManager manager) { return manager.getConfig(BuildPlannerConfig.class); }
    java.util.Set<Integer> bankItems() { return bankItems; }
    private void publishPlan(Planner planner)
    {
        bankItems = requiredItemIds(planner, materialMappings);
    }
    static java.util.Set<Integer> requiredItemIds(Planner planner, Supplies mappings)
    {
        java.util.Set<Integer> ids = new java.util.HashSet<>();
        for (Planner.Material m : planner.materials())
            for (int id : mappings.items.getOrDefault(m.name, new int[0])) ids.add(id);
        return java.util.Set.copyOf(ids);
    }
    private PlannerView view;
    private Supplies.Snapshot snapshot = Supplies.Snapshot.empty();
    private NavigationButton navigation;
    private PluginPanel panel;
    private Catalogue catalogue;
    private Supplies materialMappings;

    @Override protected void startUp() throws Exception
    {
        catalogue = Catalogue.load(gson);
        materialMappings = new Supplies(gson);
        LiveSupplies[] holder = new LiveSupplies[1];
        holder[0] = new LiveSupplies(client, itemManager, runeLiteConfig, new Supplies(gson), next ->
            SwingUtilities.invokeLater(() -> {
                if (live != holder[0]) return;
                snapshot = next;
                if (view != null) view.updateSupplies(next);
            }));
        live = holder[0];
        overlayManager.add(bankOverlay);
        Runnable init = () -> {
            panel = new PluginPanel(false) { private static final long serialVersionUID = 1L; };
            panel.setLayout(new BorderLayout());
            try { mount(catalogue); }
            catch (RuntimeException failure) { showRecovery(catalogue); }
            navigation = NavigationButton.builder().tooltip("Build Planner").icon(icon()).priority(8).panel(panel).build();
            toolbar.addNavigation(navigation);
        };
        if (SwingUtilities.isEventDispatchThread()) init.run(); else SwingUtilities.invokeAndWait(init);
    }

    @Subscribe public void onProfileChanged(ProfileChanged event)
    {
        SwingUtilities.invokeLater(() -> {
            if (panel == null) return;
            try { mount(catalogue); }
            catch (RuntimeException failure) { showRecovery(catalogue); }
        });
    }

    private void mount(Catalogue catalogue)
    {
        Planner planner = Planner.decode(catalogue, gson, config.getConfiguration(GROUP, STATE));
        panel.removeAll();
        view = new PlannerView(gson, catalogue, planner,
            () -> { config.setConfiguration(GROUP, STATE, planner.encode(gson)); publishPlan(planner); }, LinkBrowser::browse,
            (recipe, ready) -> {
                net.runelite.client.util.AsyncBufferedImage image = itemManager.getImage(recipe.iconItemId);
                if (image == null) ready.accept(null);
                else image.onLoaded(() -> ready.accept(image));
            });
        publishPlan(planner);
        view.updateLevels(construction, sailing);
        view.updateSupplies(snapshot);
        panel.add(view, BorderLayout.CENTER);
        panel.revalidate(); panel.repaint();
    }

    private void showRecovery(Catalogue catalogue)
    {
        view = null; bankItems = java.util.Set.of();
        panel.removeAll();
        JTextArea message = new JTextArea("Your saved project data could not be loaded. It has not been overwritten. You can disable this plugin to preserve it, or back it up and start a fresh planner below.");
        message.setLineWrap(true); message.setWrapStyleWord(true); message.setEditable(false);
        panel.add(message, BorderLayout.CENTER);
        JButton reset = new JButton("Back up & reset");
        reset.addActionListener(e -> {
            if (JOptionPane.showConfirmDialog(panel, "Back up saved data and reset the planner?", "Recover planner", JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION) return;
            String raw = config.getConfiguration(GROUP, STATE);
            if (raw != null) config.setConfiguration(GROUP, "recoveryBackup" + System.currentTimeMillis(), raw);
            config.unsetConfiguration(GROUP, STATE); mount(catalogue);
        });
        panel.add(reset, BorderLayout.SOUTH);
    }

    @Override protected void shutDown() throws Exception
    {
        live = null; bankItems = java.util.Set.of();
        overlayManager.remove(bankOverlay);
        Runnable stop = () -> {
            view = null; snapshot = Supplies.Snapshot.empty(); construction = -1; sailing = -1;
            if (navigation != null) toolbar.removeNavigation(navigation);
            navigation = null; panel = null;
        };
        if (SwingUtilities.isEventDispatchThread()) stop.run(); else SwingUtilities.invokeAndWait(stop);
    }

    @Subscribe public void onItemContainerChanged(net.runelite.api.events.ItemContainerChanged event)
    { LiveSupplies current=live; if (current!=null) current.containerChanged(event); }
    @Subscribe public void onGameTick(net.runelite.api.events.GameTick event)
    {
        LiveSupplies current=live; if (current==null) return;
        current.tick();
        boolean loggedIn = client.getGameState() == net.runelite.api.GameState.LOGGED_IN;
        publishLevels(current, loggedIn ? client.getBoostedSkillLevel(net.runelite.api.Skill.CONSTRUCTION) : -1,
            loggedIn ? client.getBoostedSkillLevel(net.runelite.api.Skill.SAILING) : -1);
    }
    private void publishLevels(LiveSupplies source, int con, int sail)
    {
        SwingUtilities.invokeLater(() -> {
            if (live != source) return;
            construction = con; sailing = sail;
            if (view != null) view.updateLevels(con, sail);
        });
    }
    @Subscribe public void onGameStateChanged(net.runelite.api.events.GameStateChanged event)
    { LiveSupplies current=live; if (current!=null) {
        current.stateChanged(event.getGameState());
        if (event.getGameState()!=net.runelite.api.GameState.LOGGED_IN) publishLevels(current,-1,-1);
    } }

    private static BufferedImage icon()
    {
        BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(new Color(208, 178, 112)); g.fillRoundRect(3, 2, 18, 20, 3, 3);
        g.setColor(new Color(43, 57, 58)); g.fillRect(6, 5, 12, 14);
        g.setColor(new Color(208, 178, 112));
        for (int y = 8; y < 18; y += 4) g.fillRect(8, y, 8, 1);
        g.dispose(); return image;
    }
}

package com.buildplanner;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.stream.Collectors;

public final class Catalogue
{
    private final Map<String, Recipe> byId = new LinkedHashMap<>();

    public Catalogue(Recipe[] recipes)
    {
        if (recipes == null || recipes.length == 0) throw new IllegalArgumentException("Empty catalogue");
        for (Recipe r : recipes)
        {
            if (r == null || r.id == null || r.name == null || r.name.isBlank()
                || !Arrays.asList("House", "Construction", "Sailing").contains(r.category)
                || !Arrays.asList("Any", "Raft", "Skiff", "Sloop").contains(r.boat)
                || r.construction < 1 || r.construction > 99 || r.sailing < 0 || r.sailing > 99
                || r.materials == null || r.materials.isEmpty() || r.checked == null
                || r.source == null || !r.source.startsWith("https://oldschool.runescape.wiki/w/"))
                throw new IllegalArgumentException("Invalid recipe");
            for (Map.Entry<String, Long> m : r.materials.entrySet())
                if (m.getKey() == null || m.getKey().isBlank() || m.getValue() == null || m.getValue() <= 0)
                    throw new IllegalArgumentException("Invalid materials: " + r.id);
            if (byId.putIfAbsent(r.id, r) != null) throw new IllegalArgumentException("Duplicate recipe: " + r.id);
        }
        for (Recipe r : recipes) chain(r.id); // Detect missing dependencies and cycles before displaying anything.
    }

    public static Catalogue load(Gson gson)
    {
        InputStream in = Catalogue.class.getResourceAsStream("/com/buildplanner/recipes.json");
        if (in == null) throw new IllegalStateException("Bundled recipes missing");
        try (InputStreamReader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
        {
            return new Catalogue(gson.fromJson(reader, Recipe[].class));
        }
        catch (java.io.IOException e) { throw new IllegalStateException("Cannot read recipes", e); }
    }

    public Recipe get(String id)
    {
        Recipe r = byId.get(id);
        if (r == null) throw new IllegalArgumentException("Unknown recipe: " + id);
        return r;
    }

    public List<Recipe> chain(String id)
    {
        List<Recipe> out = new ArrayList<>();
        Set<String> visited = new HashSet<>();
        while (id != null)
        {
            if (!visited.add(id)) throw new IllegalArgumentException("Cyclic prerequisite: " + id);
            Recipe r = get(id);
            out.add(r);
            id = r.previous;
        }
        Collections.reverse(out);
        return out;
    }

    public List<Recipe> search(String query, String category, String boat)
    {
        String[] words = query.strip().toLowerCase(Locale.ROOT).split("\\s+");
        return byId.values().stream()
            .filter(r -> "All".equals(category) || r.category.equals(category) || ("Construction".equals(category) && "House".equals(r.category)))
            .filter(r -> "All boats".equals(boat) || r.boat.equals("Any") || r.boat.equals(boat))
            .filter(r -> {
                String hay = (r.label() + " " + r.category + " " + String.join(" ", r.materials.keySet())).toLowerCase(Locale.ROOT);
                return Arrays.stream(words).allMatch(hay::contains);
            })
            .sorted(Comparator.comparing(Recipe::label)).collect(Collectors.toList());
    }

    public int size() { return byId.size(); }
}

package com.buildplanner;

import java.util.*;
import java.util.function.Consumer;
import net.runelite.api.*;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.widgets.Widget;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.game.ItemManager;

/** Client-thread adapter. Bank/inventory are copied together at the end of a game tick. */
final class LiveSupplies
{
    private final Client client;
    private final java.util.function.IntFunction<ItemComposition> definitions;
    private final java.util.function.IntToLongFunction priceLookup;
    private final java.util.function.BooleanSupplier wikiPrices;
    private final Supplies materials;
    private final Consumer<Supplies.Snapshot> publish;
    private long account, bankAt, priceAt;
    private boolean inventoryDirty=true, bankDirty, bankWasOpen, inventoryKnown;
    private Map<Integer,Long> bank=Map.of(), inventory=Map.of(), prices=Map.of();
    private Set<Integer> untradeable=Set.of();
    private String source="RuneLite";
    LiveSupplies(Client client, ItemManager manager, RuneLiteConfig config, Supplies materials,
        Consumer<Supplies.Snapshot> publish)
    { this(client, manager::getItemComposition, manager::getItemPrice, config::useWikiItemPrices, materials, publish); }
    LiveSupplies(Client client, java.util.function.IntFunction<ItemComposition> definitions,
        java.util.function.IntToLongFunction priceLookup, java.util.function.BooleanSupplier wikiPrices,
        Supplies materials, Consumer<Supplies.Snapshot> publish)
    { this.client=client; this.definitions=definitions; this.priceLookup=priceLookup; this.wikiPrices=wikiPrices; this.materials=materials; this.publish=publish; }

    void clear()
    {
        account=0; bankAt=0; bank=Map.of(); inventory=Map.of(); inventoryKnown=false;
        inventoryDirty=true; bankDirty=false; bankWasOpen=false;
        publish.accept(snapshot());
    }
    void stateChanged(GameState state)
    {
        if (state==GameState.LOGIN_SCREEN || state==GameState.LOGIN_SCREEN_AUTHENTICATOR
            || state==GameState.LOGGING_IN || state==GameState.HOPPING || state==GameState.CONNECTION_LOST) clear();
    }
    void containerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId()==InventoryID.BANK) bankDirty=true;
        if (event.getContainerId()==InventoryID.INV) inventoryDirty=true;
    }
    void tick()
    {
        if (client.getGameState()!=GameState.LOGGED_IN) return;
        long current=client.getAccountHash();
        if (current==0 || current==-1) return;
        if (current!=account) { clear(); account=current; }
        Widget widget=client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        boolean open=widget!=null && !widget.isHidden();
        boolean changed=false;
        // A visible bank is required to establish the first snapshot in this session.
        if ((open && (!bankWasOpen || bankAt==0)) || (bankDirty && bankAt>0)) {
            ItemContainer container=client.getItemContainer(InventoryID.BANK);
            if (container!=null) { bank=copy(container); bankAt=System.currentTimeMillis(); changed=true; }
        }
        if (inventoryDirty || !inventoryKnown || bankDirty) {
            ItemContainer container=client.getItemContainer(InventoryID.INV);
            if (container!=null) {
                Map<Integer,Long> next=copy(container);
                changed |= !inventoryKnown || !next.equals(inventory);
                inventory=next; inventoryKnown=true;
            }
        }
        inventoryDirty=false; bankDirty=false; bankWasOpen=open;
        String wanted=wikiPrices.getAsBoolean()?"Wiki market prices (RuneLite cache)":"GE guide prices (RuneLite cache)";
        if (System.currentTimeMillis()-priceAt>=60_000 || !wanted.equals(source)) {
            Map<Integer,Long> next=new HashMap<>(); Set<Integer> unavailable=new HashSet<>();
            for (int[] ids : materials.items.values()) for (int id : ids) {
                if (!definitions.apply(id).isGeTradeable()) unavailable.add(id);
                else {
                    long price=priceLookup.applyAsLong(id);
                    if (price>0) next.put(id,price);
                }
            }
            prices=next; untradeable=unavailable; source=wanted; priceAt=System.currentTimeMillis(); changed=true;
        }
        if (changed) publish.accept(snapshot());
    }
    private Supplies.Snapshot snapshot()
    { return new Supplies.Snapshot(bank,inventory,inventoryKnown,bankAt,prices,untradeable,priceAt,source); }

    private Map<Integer,Long> copy(ItemContainer container)
    {
        Map<Integer,Long> quantities=new HashMap<>();
        for (Item item : container.getItems()) {
            if (item==null || item.getId()<0 || item.getQuantity()<=0) continue;
            ItemComposition definition=definitions.apply(item.getId());
            if (definition.getPlaceholderTemplateId()!=-1) continue;
            int id=definition.getNote()!=-1?definition.getLinkedNoteId():item.getId();
            quantities.merge(id,(long)item.getQuantity(),Long::sum);
        }
        return quantities;
    }
}

package com.buildplanner;

import com.google.gson.Gson;
import java.util.*;

/** Pure planning logic, independently testable without the game client. All edits run on the Swing EDT. */
public final class Planner
{
    public static final int MAX_QUANTITY = 1_000_000;
    public static final long MAX_OWNED = 1_000_000_000_000L;

    public static final class Entry
    {
        public String recipeId;
        public int quantity;
        public boolean fromScratch;
        public boolean completed;
        Entry(String id, int count, boolean all) { recipeId = id; quantity = count; fromScratch = all; }
    }
    public static final class Project
    {
        public String id = UUID.randomUUID().toString();
        public String name;
        public boolean manualCounts;
        public List<Entry> entries = new ArrayList<>();
        public Map<String, Long> owned = new TreeMap<>();
        Project(String name) { this.name = name; }
        @Override public String toString() { return name; }
    }
    public static final class State
    {
        public int version = 1;
        public String selected;
        public List<Project> projects = new ArrayList<>();
    }
    public static final class Material
    {
        public final String name;
        public final long required, owned, missing;
        Material(String name, long required, long owned)
        {
            this.name = name; this.required = required; this.owned = owned;
            this.missing = Math.max(0, required - owned);
        }
    }

    private final Catalogue catalogue;
    public final State state;
    public Planner(Catalogue catalogue, State state)
    {
        this.catalogue = catalogue; this.state = state;
        validate();
    }
    public static Planner fresh(Catalogue catalogue)
    {
        State s = new State(); Project p = new Project("My builds");
        s.projects.add(p); s.selected = p.id;
        return new Planner(catalogue, s);
    }
    public static Planner decode(Catalogue c, Gson g, String json)
    {
        if (json == null || json.isBlank()) return fresh(c);
        return new Planner(c, g.fromJson(json, State.class));
    }
    public String encode(Gson g) { return g.toJson(state); }
    private void validate()
    {
        if (state == null || state.version != 1 || state.projects == null || state.projects.isEmpty()
            || state.projects.size() > 100) throw new IllegalArgumentException("Unsupported or invalid saved planner");
        Set<String> ids = new HashSet<>();
        for (Project p : state.projects)
        {
            if (p == null || p.id == null || !ids.add(p.id) || p.entries == null || p.owned == null)
                throw new IllegalArgumentException("Invalid saved project");
            checkName(p.name);
            Set<String> entries = new HashSet<>();
            for (Entry e : p.entries)
            {
                if (e == null) throw new IllegalArgumentException("Invalid saved entry");
                catalogue.get(e.recipeId); checkQuantity(e.quantity);
                if (!entries.add(e.recipeId + ":" + e.fromScratch + ":" + e.completed)) throw new IllegalArgumentException("Duplicate saved entry");
            }
            for (Map.Entry<String, Long> m : p.owned.entrySet())
                if (m.getKey() == null || m.getKey().isBlank() || m.getValue() == null || m.getValue() < 0 || m.getValue() > MAX_OWNED)
                    throw new IllegalArgumentException("Invalid saved material count");
        }
        if (!ids.contains(state.selected)) state.selected = state.projects.get(0).id;
    }
    private static void checkQuantity(int n)
    {
        if (n < 1 || n > MAX_QUANTITY) throw new IllegalArgumentException("Quantity must be 1–1,000,000");
    }
    private static void checkName(String name)
    {
        if (name == null || name.isBlank() || name.length() > 60) throw new IllegalArgumentException("Use a project name of 1–60 characters");
    }
    public Project current()
    {
        return state.projects.stream().filter(p -> p.id.equals(state.selected)).findFirst().orElseThrow(IllegalStateException::new);
    }
    public void select(Project p)
    {
        if (!state.projects.contains(p)) throw new IllegalArgumentException("Unknown project");
        state.selected = p.id;
    }
    public Project create(String name)
    {
        checkName(name);
        if (state.projects.size() >= 100) throw new IllegalArgumentException("Project limit reached (100)");
        Project p = new Project(name.strip()); state.projects.add(p); state.selected = p.id; return p;
    }
    public void rename(String name) { checkName(name); current().name = name.strip(); }
    public void deleteCurrent()
    {
        state.projects.remove(current());
        if (state.projects.isEmpty()) state.projects.add(new Project("My builds"));
        state.selected = state.projects.get(0).id;
    }
    public void add(String id, int quantity, boolean fromScratch)
    {
        catalogue.get(id); checkQuantity(quantity);
        if (catalogue.get(id).previous == null) fromScratch = false;
        for (Entry e : current().entries)
            if (!e.completed && e.recipeId.equals(id) && e.fromScratch == fromScratch)
            {
                int total = Math.addExact(e.quantity, quantity); checkQuantity(total); e.quantity = total; return;
            }
        current().entries.add(new Entry(id, quantity, fromScratch));
    }
    public void quantity(Entry entry, int quantity) { checkQuantity(quantity); entry.quantity = quantity; }
    public void complete(Entry entry, boolean completed)
    {
        if (!current().entries.contains(entry)) throw new IllegalArgumentException("Unknown build");
        for (Entry other : current().entries)
            if (other != entry && other.completed == completed && other.recipeId.equals(entry.recipeId)
                && other.fromScratch == entry.fromScratch)
            {
                int total = Math.addExact(other.quantity, entry.quantity); checkQuantity(total);
                other.quantity = total; current().entries.remove(entry); return;
            }
        entry.completed = completed;
    }
    public void remove(Entry entry) { current().entries.remove(entry); }
    public void owned(String material, long quantity)
    {
        if (material == null || material.isBlank() || quantity < 0 || quantity > MAX_OWNED)
            throw new IllegalArgumentException("Owned must be 0–1,000,000,000,000");
        current().owned.put(material, quantity);
    }
    public Map<String, Long> requirements(String id, int count, boolean fromScratch)
    {
        checkQuantity(count);
        Map<String, Long> total = new TreeMap<>();
        for (Recipe r : fromScratch ? catalogue.chain(id) : Collections.singletonList(catalogue.get(id)))
            r.materials.forEach((name, n) -> total.merge(name, Math.multiplyExact(n, count), Math::addExact));
        return total;
    }
    public List<Material> materials()
    {
        Map<String, Long> total = new TreeMap<>();
        for (Entry e : current().entries)
            if (!e.completed) requirements(e.recipeId, e.quantity, e.fromScratch).forEach((name, n) -> total.merge(name, n, Math::addExact));
        List<Material> out = new ArrayList<>();
        total.forEach((name, n) -> out.add(new Material(name, n, current().owned.getOrDefault(name, 0L))));
        return out;
    }
    public String shoppingList()
    {
        StringBuilder s = new StringBuilder(current().name + " — Build Planner\nManual counts; not a bank scan.\n\n");
        for (Material m : materials())
            s.append(m.name).append(": need ").append(m.required).append(", have ").append(m.owned).append(", missing ").append(m.missing).append('\n');
        s.append("\nTools and unlock requirements: consult each recipe. Room costs and intermediate crafting are excluded.\n");
        for (Entry e : current().entries)
        {
            Recipe r = catalogue.get(e.recipeId);
            if (e.completed) { s.append("Completed: ").append(e.quantity).append(" × ").append(r.label()).append('\n'); continue; }
            s.append(e.quantity).append(" × ").append(r.label()).append(e.fromScratch ? " (from scratch)" : " (this step only)").append('\n');
            if (!e.fromScratch && r.previous != null) s.append("  Must already have: ").append(catalogue.get(r.previous).name).append('\n');
            s.append("  ").append(r.source).append('\n');
        }
        return s.toString();
    }
}

